Json::Value WechatService::exchangeCodeForToken(const std::string &code) const
{
    if (config_.appId.empty() || config_.appSecret.empty() || config_.callbackBaseUrl.empty())
    {
        throw common::AppException(
            "WECHAT_NOT_CONFIGURED",
            "Set WECHAT_APP_ID, WECHAT_APP_SECRET, and WECHAT_CALLBACK_BASE_URL before enabling real WeChat login.",
            drogon::k503ServiceUnavailable);
    }

    auto tokenClient = drogon::HttpClient::newHttpClient("https://api.weixin.qq.com");
    auto tokenRequest = drogon::HttpRequest::newHttpRequest();
    tokenRequest->setMethod(drogon::Get);
    tokenRequest->setPath(
        "/sns/oauth2/access_token?appid=" + urlEncode(config_.appId) +
        "&secret=" + urlEncode(config_.appSecret) +
        "&code=" + urlEncode(code) +
        "&grant_type=authorization_code");
    const auto [tokenResult, tokenResponse] = tokenClient->sendRequest(tokenRequest);
    if (tokenResult != drogon::ReqResult::Ok || !tokenResponse)
    {
        throw common::AppException("WECHAT_AUTH_FAILED", "Failed to request WeChat access_token", drogon::k502BadGateway);
    }
    const auto tokenPayload = parseJsonBody(tokenResponse);
    if (tokenResponse->statusCode() < drogon::k200OK || tokenResponse->statusCode() >= drogon::k300MultipleChoices ||
        tokenPayload.isMember("errcode"))
    {
        const auto message = tokenPayload.get("errmsg", responseText(tokenResponse)).asString();
        throw common::AppException("WECHAT_AUTH_FAILED", "WeChat access_token error: " + message, drogon::k502BadGateway);
    }

    const auto accessToken = tokenPayload.get("access_token", "").asString();
    const auto openid = tokenPayload.get("openid", "").asString();
    if (accessToken.empty() || openid.empty())
    {
        throw common::AppException("WECHAT_AUTH_FAILED", "WeChat response did not include access_token/openid", drogon::k502BadGateway);
    }

    auto userClient = drogon::HttpClient::newHttpClient("https://api.weixin.qq.com");
    auto userRequest = drogon::HttpRequest::newHttpRequest();
    userRequest->setMethod(drogon::Get);
    userRequest->setPath(
        "/sns/userinfo?access_token=" + urlEncode(accessToken) +
        "&openid=" + urlEncode(openid) +
        "&lang=zh_CN");
    const auto [userResult, userResponse] = userClient->sendRequest(userRequest);

    Json::Value out(Json::objectValue);
    out["openid"] = openid;
    out["unionid"] = tokenPayload.get("unionid", "").asString();
    if (userResult == drogon::ReqResult::Ok && userResponse &&
        userResponse->statusCode() >= drogon::k200OK && userResponse->statusCode() < drogon::k300MultipleChoices)
    {
        const auto userPayload = parseJsonBody(userResponse);
        if (!userPayload.isMember("errcode"))
        {
            out["nickname"] = userPayload.get("nickname", "").asString();
            out["headimgurl"] = userPayload.get("headimgurl", "").asString();
            out["unionid"] = userPayload.get("unionid", out["unionid"]).asString();
        }
    }
    return out;
}

